<?php

declare(strict_types=1);require_once __DIR__.'/../../includes/module-admin.php';$pdo=cmsAdminModuleBoot('partners');$base='/admin/partners.php';
if($_SERVER['REQUEST_METHOD']==='POST'){cmsVerifyCsrf();$a=cmsStr($_POST['action']??'save',20);$id=cmsInt($_POST['id']??0);if($a==='delete'&&$id){$s=$pdo->prepare('SELECT logo_path FROM partners WHERE id=:id');$s->execute([':id'=>$id]);$old=$s->fetchColumn();$pdo->prepare('DELETE FROM partners WHERE id=:id')->execute([':id'=>$id]);if(is_string($old)&&$old!=='')cmsDeleteLocalUpload($old);cmsAudit('partners.delete','partners',(string)$id);cmsAdminRedirect($base,'تم الحذف.');}if($a==='toggle'&&$id){$pdo->prepare('UPDATE partners SET is_active=1-is_active WHERE id=:id')->execute([':id'=>$id]);cmsAudit('partners.toggle','partners',(string)$id);cmsAdminRedirect($base,'تم تحديث الحالة.');}
$nameAr=cmsStr($_POST['name_ar']??'',255);$nameEn=cmsStr($_POST['name_en']??'',255);$url=cmsStr($_POST['website_url']??'',500);$sort=cmsInt($_POST['sort_order']??0);$active=cmsBool($_POST['is_active']??0);if($nameAr===''||$nameEn===''||!cmsValidUrlOrBlank($url))cmsAdminRedirect($base,'راجع الاسم والرابط.');$logo=cmsUploadFile('logo','partners',['jpg','jpeg','png','webp'],5*1024*1024);if($id){$s=$pdo->prepare('SELECT logo_path FROM partners WHERE id=:id');$s->execute([':id'=>$id]);$old=(string)($s->fetchColumn()?:'');$logoPath=$logo??$old;$q=$pdo->prepare('UPDATE partners SET name_ar=:ar,name_en=:en,logo_path=:l,website_url=:u,sort_order=:s,is_active=:i WHERE id=:id');$q->execute([':ar'=>$nameAr,':en'=>$nameEn,':l'=>$logoPath?:null,':u'=>$url?:null,':s'=>$sort,':i'=>$active,':id'=>$id]);if($logo&&$old&&$old!==$logo)cmsDeleteLocalUpload($old);$act='partners.update';}else{$q=$pdo->prepare('INSERT INTO partners(name_ar,name_en,logo_path,website_url,sort_order,is_active) VALUES(:ar,:en,:l,:u,:s,:i)');$q->execute([':ar'=>$nameAr,':en'=>$nameEn,':l'=>$logo,':u'=>$url?:null,':s'=>$sort,':i'=>$active]);$act='partners.create';}cmsAudit($act,'partners',(string)$id);cmsAdminRedirect($base,'تم الحفظ.');}
$edit=null;if($id=cmsInt($_GET['edit']??0)){$s=$pdo->prepare('SELECT * FROM partners WHERE id=:id');$s->execute([':id'=>$id]);$edit=$s->fetch()?:null;}$rows=$pdo->query('SELECT * FROM partners ORDER BY sort_order,id')->fetchAll();cmsAdminHead('الشركاء');cmsAdminSidebar('partners');cmsAdminTopbar('الشركاء');?>
<div class="content"><?php if($m=cmsAdminMessage()):?><div class="alert"><?=cmsE($m)?></div><?php endif;?><div class="split"><section class="card"><h2>الشركاء</h2><div class="table-wrap"><table class="table"><thead><tr><th>الشعار</th><th>الاسم</th><th>الحالة</th><th>الترتيب</th><th>إجراء</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?php if($r['logo_path']):?><img class="thumb" src="<?=cmsE($r['logo_path'])?>" alt=""><?php endif;?></td><td><?=cmsE($r['name_ar'])?><div class="muted"><?=cmsE($r['name_en'])?></div></td><td><span class="pill <?=$r['is_active']?'ok':'bad'?>"><?=$r['is_active']?'ظاهر':'مخفي'?></span></td><td><?=$r['sort_order']?></td><td><div class="actions"><a class="btn" href="?edit=<?=$r['id']?>">تعديل</a><form method="post"><?=cmsCsrfField()?><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn" name="action" value="toggle">إظهار/إخفاء</button><button class="btn danger" name="action" value="delete" onclick="return confirm('حذف الشريك؟')">حذف</button></form></div></td></tr><?php endforeach;?></tbody></table></div></section><section class="card"><h2><?=$edit?'تعديل':'إضافة شريك'?></h2><form method="post" enctype="multipart/form-data"><?=cmsCsrfField()?><input type="hidden" name="id" value="<?=$edit['id']??0?>"><div class="form-grid"><label class="field"><span>الاسم AR</span><input name="name_ar" required value="<?=cmsE((string)($edit['name_ar']??''))?>"></label><label class="field"><span>Name EN</span><input name="name_en" required value="<?=cmsE((string)($edit['name_en']??''))?>"></label><label class="field"><span>الموقع</span><input name="website_url" value="<?=cmsE((string)($edit['website_url']??''))?>" placeholder="https://"></label><label class="field"><span>الشعار</span><input type="file" name="logo" accept="image/*"></label><label class="field"><span>الترتيب</span><input type="number" name="sort_order" value="<?=intval($edit['sort_order']??0)?>"></label><label class="module-row"><span>ظاهر</span><input class="check" type="checkbox" name="is_active" value="1" <?=cmsChecked($edit['is_active']??1)?>></label></div><div class="actions" style="margin-top:16px"><button class="btn primary">حفظ</button><?php if($edit):?><a class="btn" href="<?=$base?>">إلغاء</a><?php endif;?></div></form></section></div></div><?php cmsAdminEnd();
